import os


def _require_key(name):
    key = os.environ.get(name)
    if not key:
        raise EnvironmentError(f"Missing environment variable: {name}")
    return key


def create_chat_client(provider: str):
    """Return a chat client for 'openai', 'anthropic' or 'google'."""
    if not isinstance(provider, str):
        raise ValueError(f"Unknown provider: {provider!r}")
    name = provider.strip().lower()

    if name == "openai":
        key = _require_key("OPENAI_API_KEY")
        from openai import OpenAI
        return OpenAI(api_key=key)

    if name == "anthropic":
        key = _require_key("ANTHROPIC_API_KEY")
        import anthropic
        return anthropic.Anthropic(api_key=key)

    if name == "google":
        key = _require_key("GOOGLE_API_KEY")
        from google import genai
        return genai.Client(api_key=key)

    raise ValueError(f"Unknown provider: {provider!r}. Use 'openai', 'anthropic', or 'google'.")


